/**
 * 本机存档按账号分桶。
 *
 * 2026-10-14 之前，知识卡、单词本、书架收的词各只有一份本机存档：
 * 同一台设备上不管登进哪个账号（包括刚注册的全新账号），打开看到的
 * 都是这份旧数据 —— 新账号并不「新」。现在登录后写进「键::账号 id」
 * 这一桶，新账号从空的开始；没登录时还是原来的裸键 —— 老数据留在
 * 原地，不丢，也不并进任何账号（登录自己的账号看到的只有自己账号里
 * 存的那些）。
 *
 * 用户 2026-10-14 的原话：「知识收藏也是，新用户打开是新的」。
 */
export function scopedLocalKey(
  baseKey: string,
  userId?: string | null,
): string {
  return userId ? `${baseKey}::${userId}` : baseKey;
}
